import{_ as a,o as t,c as n,ao as i}from"./chunks/framework.Bj6zxD8x.js";const g=JSON.parse('{"title":"Manual — reading path","description":"","frontmatter":{},"headers":[],"relativePath":"manual/index.md","filePath":"manual/index.md","lastUpdated":null}'),l={name:"manual/index.md"};function o(s,e,r,d,c,h){return t(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="man-index" tabindex="-1">Manual — reading path <a class="header-anchor" href="#man-index" aria-label="Permalink to &quot;Manual — reading path {#man-index}&quot;">​</a></h1><p>The Manual answers <em>how do I do this</em>. It says what to call, what the arguments mean, and where each choice bites. The <strong>why</strong> is in <a href="/MeanFieldHomogenization.jl/v0.29/theory/index#th-index">Theory — reading path</a>, and the exhaustive signatures are in the API section, which the pages here link into rather than repeat.</p><p>If you have never used the package, <a href="/MeanFieldHomogenization.jl/v0.29/quickstart#getting-started">Getting started</a> and then <a href="/MeanFieldHomogenization.jl/v0.29/manual/schemes#man-schemes">Schemes and RVEs</a> are the two pages that make everything else readable.</p><h2 id="Inclusions:-which-page-for-which-morphology" tabindex="-1">Inclusions: which page for which morphology <a class="header-anchor" href="#Inclusions:-which-page-for-which-morphology" aria-label="Permalink to &quot;Inclusions: which page for which morphology {#Inclusions:-which-page-for-which-morphology}&quot;">​</a></h2><p>Everything a scheme needs from a phase is one response tensor. What differs between the pages below is <em>how</em> that tensor is obtained — a closed form, a recurrence, a grid of Gaussians, a mesh, a network — and every one of them ends up in the same <code>add_phase!</code> call.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Your morphology</th><th style="text-align:left;">Page</th><th style="text-align:left;">How the response is obtained</th></tr></thead><tbody><tr><td style="text-align:left;">an ellipsoid, or one of its limits</td><td style="text-align:left;"><a href="/MeanFieldHomogenization.jl/v0.29/manual/ellipsoidal_inclusions#man-ellipsoidal-inclusions">Ellipsoidal inclusions</a></td><td style="text-align:left;">Eshelby&#39;s closed form</td></tr><tr><td style="text-align:left;">a fiber, a cylinder</td><td style="text-align:left;"><a href="/MeanFieldHomogenization.jl/v0.29/manual/cylindrical_inclusions#man-cylindrical-inclusions">Cylindrical inclusions</a></td><td style="text-align:left;">the same, in the cylindrical limit</td></tr><tr><td style="text-align:left;">a crack, a family of cracks</td><td style="text-align:left;"><a href="/MeanFieldHomogenization.jl/v0.29/manual/cracks#man-cracks">Cracks</a></td><td style="text-align:left;">the crack-opening tensor and its algebra</td></tr><tr><td style="text-align:left;">a flat crack of any contour, contacts between its faces</td><td style="text-align:left;"><a href="/MeanFieldHomogenization.jl/v0.29/manual/planar_cracks#man-planar-cracks">Planar cracks of any contour</a></td><td style="text-align:left;">its integral equation, solved on a grid of Gaussians</td></tr><tr><td style="text-align:left;">a coated particle, an interphase</td><td style="text-align:left;"><a href="/MeanFieldHomogenization.jl/v0.29/manual/layered_inclusions#man-layered">Layered inclusions</a></td><td style="text-align:left;">a recurrence over the layers</td></tr><tr><td style="text-align:left;">a ring-shaped pore</td><td style="text-align:left;"><a href="/MeanFieldHomogenization.jl/v0.29/manual/toroidal_inclusions#man-toroidal-inclusions">Toroidal inclusions</a></td><td style="text-align:left;">a series of toroidal harmonics</td></tr><tr><td style="text-align:left;">a grain, a pore, a fiber or a slit in a flow, whose size matters</td><td style="text-align:left;"><a href="/MeanFieldHomogenization.jl/v0.29/manual/brinkman_inclusions#man-brinkman">Brinkman inclusions</a></td><td style="text-align:left;">Brinkman&#39;s equation around the inclusion, which gives it a size and no Hill tensor</td></tr><tr><td style="text-align:left;">a prismatic pore whose section is not an ellipse</td><td style="text-align:left;"><a href="/MeanFieldHomogenization.jl/v0.29/manual/conformal_holes#man-conformal-holes">Conformal holes</a></td><td style="text-align:left;">complex potentials on a conformal map</td></tr><tr><td style="text-align:left;">a two-dimensional medium, in plane strain or in plane stress</td><td style="text-align:left;"><a href="/MeanFieldHomogenization.jl/v0.29/manual/plane_problems#man-plane-problems">Plane problems</a></td><td style="text-align:left;">the schemes on cylinders, after a change of moduli</td></tr><tr><td style="text-align:left;">anything else, from your own code</td><td style="text-align:left;"><a href="/MeanFieldHomogenization.jl/v0.29/manual/custom_inclusions#man-custom-inclusions">Custom inclusions</a></td><td style="text-align:left;">you supply it, through one of three entry levels</td></tr><tr><td style="text-align:left;">a shape of any kind, without a mesh</td><td style="text-align:left;"><a href="/MeanFieldHomogenization.jl/v0.29/manual/gaussian_inclusions#man-gaussian-inclusions">Heterogeneities of any shape</a></td><td style="text-align:left;">its integral equation, solved on a grid of Gaussians</td></tr><tr><td style="text-align:left;">a shape with no closed form</td><td style="text-align:left;"><a href="/MeanFieldHomogenization.jl/v0.29/manual/fe_inclusions#man-fe-inclusions">Finite-element inclusions</a></td><td style="text-align:left;">one Eshelby cell, solved</td></tr><tr><td style="text-align:left;">the same, but cheap and differentiable</td><td style="text-align:left;"><a href="/MeanFieldHomogenization.jl/v0.29/manual/neural_inclusions#man-neural-inclusions">Neural-surrogate inclusions</a></td><td style="text-align:left;">a network trained on it</td></tr></tbody></table><p><a href="/MeanFieldHomogenization.jl/v0.29/manual/inclusion_gallery#man-inclusion-gallery">The inclusion gallery</a> draws them, if you would rather recognize a shape than read a table. <a href="/MeanFieldHomogenization.jl/v0.29/manual/choosing_an_inclusion#man-choosing-inclusion">Choosing an inclusion</a> compares the routes: the reference medium each accepts, the derivatives it gives, its accuracy and its cost.</p><h2 id="The-rest" tabindex="-1">The rest <a class="header-anchor" href="#The-rest" aria-label="Permalink to &quot;The rest {#The-rest}&quot;">​</a></h2><ul><li><p><strong><a href="/MeanFieldHomogenization.jl/v0.29/manual/schemes#man-schemes">Schemes and RVEs</a></strong> — building a cell, choosing an estimate, and what each scheme assumes. Then <a href="/MeanFieldHomogenization.jl/v0.29/manual/particle_assemblies#man-assemblies">particle assemblies</a> for a population rather than a phase, and <a href="/MeanFieldHomogenization.jl/v0.29/manual/multiscale#man-multiscale">multiscale</a> for a cell inside a cell.</p></li><li><p><strong><a href="/MeanFieldHomogenization.jl/v0.29/manual/laminates#man-laminates">Laminates</a></strong> — periodic homogenization, exact rather than estimated, and a different construction from everything above.</p></li><li><p><strong>Beyond elasticity</strong> — <a href="/MeanFieldHomogenization.jl/v0.29/manual/conductivity#man-conductivity">conduction</a>, <a href="/MeanFieldHomogenization.jl/v0.29/manual/nonaging_viscoelasticity#man-viscoelasticity-nonaging">non-aging viscoelasticity</a> with its <a href="/MeanFieldHomogenization.jl/v0.29/manual/rheological_models#man-rheological-models">rheological models</a> and <a href="/MeanFieldHomogenization.jl/v0.29/manual/nonaging_viscoelasticity#man-laplace-inversion">Laplace–Carson inversion</a>, <a href="/MeanFieldHomogenization.jl/v0.29/manual/aging_viscoelasticity#man-viscoelasticity">aging viscoelasticity</a>, and <a href="/MeanFieldHomogenization.jl/v0.29/manual/poromechanics#manual-poromechanics">poromechanics</a>.</p></li><li><p><strong><a href="/MeanFieldHomogenization.jl/v0.29/manual/sensitivities#man-sensitivities">Sensitivities</a></strong> — differentiating an effective property with respect to a modulus, a fraction or a shape parameter, and which inclusion types can and cannot serve that.</p></li><li><p><strong><a href="/MeanFieldHomogenization.jl/v0.29/manual/parallelism#man-parallelism">Parallelism</a></strong> — where the package computes in parallel: the quadrature points of a finite-element mesh.</p></li><li><p><strong><a href="/MeanFieldHomogenization.jl/v0.29/manual/elliptic_examples#man-elliptic-examples">Elliptic integrals: examples</a></strong> — the special functions of the closed forms, called directly.</p></li></ul><p>Finite elements appear twice in this package and the two are opposite: <a href="/MeanFieldHomogenization.jl/v0.29/manual/fe_inclusions#man-fe-inclusions">finite-element inclusions</a> are a solver called <em>inside</em> homogenization, while <a href="/MeanFieldHomogenization.jl/v0.29/fe_coupling/index#fe-coupling">finite-element coupling</a> is homogenization called inside a solver, as a constitutive law at a Gauss point.</p>',10)])])}const u=a(l,[["render",o]]);export{g as __pageData,u as default};
